import{c as a,Q as e,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const A=JSON.parse('{"title":"AI越强，人越忙：一个住在未来的人说了什么","description":"","frontmatter":{"url":"https://x.com/vista8/status/2059822354969325611","title":"AI越强，人越忙：一个住在未来的人说了什么","author":"向阳乔木","archived":"2026-05-28T00:00:00.000Z","handle":"@vista8","published":"2026-05-28T00:00:00.000Z","stats":"58 likes · 12 retweets · 101 bookmarks · 20099 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-05-28-@vista8-325611.md","filePath":"research/tweets/2026-05-28-@vista8-325611.md","lastUpdated":1780990164000}'),n={name:"research/tweets/2026-05-28-@vista8-325611.md"};function i(d,t,s,l,h,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ai越强-人越忙-一个住在未来的人说了什么-—-vista8" tabindex="-1">AI越强，人越忙：一个住在未来的人说了什么 — @vista8 <a class="header-anchor" href="#ai越强-人越忙-一个住在未来的人说了什么-—-vista8" aria-label="Permalink to &quot;AI越强，人越忙：一个住在未来的人说了什么 — @vista8&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/vista8/status/2059822354969325611" target="_blank" rel="noreferrer">https://x.com/vista8/status/2059822354969325611</a><strong>作者</strong>：向阳乔木（@vista8） <strong>發布日期</strong>：2026-05-28 <strong>收錄日期</strong>：2026-05-28 <strong>類型</strong>：Twitter Article <strong>統計</strong>：58 likes · 12 retweets · 101 bookmarks · 20099 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>著名PM人Lenny访谈了Every公司的CEO，很多观点犀利且反共识，让AI写一篇总结。</p><blockquote><p>原始视频：<a href="https://www.youtube.com/watch?v=4D3hDmGhFhA" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=4D3hDmGhFhA</a> 一家 30 人的公司，全员 AI 重度用户，人人用 Codex 和 Claude Code 干活。 按理说，这种公司应该越来越精简才对。 但过去一年，他们的员工人数翻了一倍。 这家公司叫 Every，CEO 叫 Dan Shipper。 他不是在硅谷的实验室里预测未来，他是真的住在未来。 工程师、编辑、销售、客服，所有人都在用最新的AI工具干活，然后 Dan 会把他们实战的经验和观察写出来。 去年他说 Claude Code 被严重低估，没人信，后来 Anthropic 围绕这个方向建了整个产品线。 所以当他说&quot;AI 越强，人反而越忙&quot;，值得认真听一听。</p></blockquote><h2 id="自动化是个谎言" tabindex="-1">自动化是个谎言 <a class="header-anchor" href="#自动化是个谎言" aria-label="Permalink to &quot;自动化是个谎言&quot;">​</a></h2><p>[圖 1] Dan 说这不是在抱怨，他是在描述一个他亲身经历的悖论。 他自己做了一个Benchmark，叫&quot;高级工程师基准测试&quot;。 起因很狼狈：他把自己的写作工具 Proof 用 vibe coding 做出来，上线第二天服务器每隔 10 分钟就崩一次。 他让 Codex 修，Codex 说修好了，然后又冒出四个新 bug，循环往复，一晚上没睡着。 后来他请了两位真正的高级工程师，分别独立重写了这个代码库。 于是他有了这个&quot;高级工程师基准测试&quot;：让 AI 接手同一个烂摊子，从头重写。 结果：几乎所有模型得分在 30 分左右。人类高级工程师能到 85 到 90 分。 GPT-5.5 是唯一的异类，跳到了 62 分。 而且它是唯一一个真的敢推倒重来的模型，其他模型接到&quot;去修这些 bug&quot;的指令，就真的去一个一个修 bug 了。 人类高级工程师会怎么做？ 他会先扫一眼代码库，然后说：&quot;这玩意儿是坨屎，我们得重写，我知道你不想听，但就是这样。&quot; 他自己判断出来的。 模型能解决被定义清楚的问题，但&quot;发现这个问题需要被重新定义&quot;这件事，模型还不会主动做。 基准测试的分数在涨，但它永远只能测量人类已经想清楚、能打分的那部分工作。 剩下那部分，没法打分，因为你得先想到要问这个问题。 这就是为什么 Every 的人越招越多。 每一个 Agent 背后，都需要一个真正关心它在做什么的人。 自动化没有消灭工作，它创造了新的工作：管理自动化本身。 Dan 把这叫做&quot;每个 Agent 都需要一个人&quot;。</p><h2 id="工作会分裂成两种形态" tabindex="-1">工作会分裂成两种形态 <a class="header-anchor" href="#工作会分裂成两种形态" aria-label="Permalink to &quot;工作会分裂成两种形态&quot;">​</a></h2><p>[圖 2] Dan 的预测是：未来一年内，大多数人的工作方式会朝两个方向同时演化。 第一种：公司共用一个超级 Agent。 不是每个人一个私人助理，而是整个公司共用一个 Agent，挂在 Slack 里，所有人都能调用。 Shopify 已经有了，Ramp 也有了。 Dan 最初以为每个人都会有自己的私人 Agent，像《黄金罗盘》里每个人肩上的精灵，是灵魂的一部分。</p><blockquote><p>黄金罗盘一口气解读版 <a href="https://www.bilibili.com/video/BV156421c74o/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV156421c74o/</a> 他对这个图景着迷了很久，然后彻底改变了看法。 原因很简单：Agent 需要有人照料它。 OpenClaw 刚出来的时候，Every 所有人都兴冲冲地设置了自己的 Agent，然后一个个放弃了。 因为它会坏，要 SSH 进服务器，要不停地调整，大多数人坚持不了多久。 一旦没人关心它在做什么，它就会悄悄变得没用。 所以现实的路径是：先有一个公司级别的通用 Agent，由专人负责维护，再随着模型变得更可靠，逐渐向下分裂出团队级别、个人级别的 Agent。 这个专门负责维护 Agent 的人，Dan 叫他&quot;前沿部署工程师&quot;，Every 内部已经有这样的岗位了。 前沿部署工程师模式（Forward Deployed Engineer，FDE）起源于Palantir，其核心在于通过&quot;驻场工程师+业务专家&quot;的协同模式，将技术能力与业务需求深度融合. 第二种：Codex 或 Claude Code 成为新的工作操作系统。 这是 Dan 更兴奋的部分，也是更难一句话说清楚的部分。 他现在处理邮件的方式是：让 Codex 打开内置浏览器，把所有邮件聚合到一个页面，然后他对着屏幕说话。 &quot;这封律师的问题，去把过去四年的文件整理成报告发过去。&quot; Codex 就去做了。 他已经连续 10 天保持收件箱清零，这对他来说是从没有过的事。 写文章也一样。 他在 Codex 的内置浏览器里打开 Proof，Codex 能看到他在写什么，他也能看到 Codex 在做什么，两者实时协作。 招人也是，他想找一个在 General Assembly 做过技术教育、现在又对 AI 感兴趣的人，直接跟 Codex 说。 然后他就做别的事了，回来发现 Codex 找到了一个完全符合条件的人，还在 Twitter 上关注了他。 Dan 直接发了私信，约了顿饭。 过去我们把 AI 嵌进 SaaS 工具，未来是把 SaaS 工具放进 AI Agent 里跑。 他在 Codex 里用 Proof，用的是他自己的 token，不是 Proof 这个产品的 token。 SaaS 厂商不需要烧钱堆 AI 功能，用户把 AI 带过来，SaaS 只需要让自己对人和 Agent 都友好就够了。 利润率反而可能回升。</p></blockquote><h2 id="cli-时代已经结束了" tabindex="-1">CLI 时代已经结束了 <a class="header-anchor" href="#cli-时代已经结束了" aria-label="Permalink to &quot;CLI 时代已经结束了&quot;">​</a></h2><p>[圖 3] Dan 说得很直接：CLI 的时代过去了，我们把它速通了。 Claude Code 火起来的时候，很多人以为是终端命令行的魔力让它好用。 Dan 认为这个判断是错的。 真正的原因是 Agent 在本地机器上有完整的访问权限，以及网上有大量关于如何使用终端的内容，让模型学得很好。这和 CLI 本身没什么关系。 Every 内部，大多数技术人员已经不把终端当主要工作界面了。 偶尔还会切进去，但主战场是 Codex、Claude Code、Cursor 这些有真正界面的工具。 GUI 本来就是为了让人更舒服而发明的，这个逻辑没有变过。</p><h2 id="saas-不会死-agent-会给它带来更多用户" tabindex="-1">SaaS 不会死，Agent 会给它带来更多用户 <a class="header-anchor" href="#saas-不会死-agent-会给它带来更多用户" aria-label="Permalink to &quot;SaaS 不会死，Agent 会给它带来更多用户&quot;">​</a></h2><p>[圖 4] Dan 说他现在会买 SaaS 股票。 大家都在说 Agent 会让人绕过 SaaS，直接用 AI 干活。 但 Dan 的观察是反过来的：Agent 不会替代 SaaS 的用户，它会成为 SaaS 新的用户。 Every 内部人人都用 Codex 和 Claude Code，但他们的 SaaS 支出比去年还高。 因为 Agent 在用 SaaS，大量的 Agent，高频次地调用。 需求在爆炸，不是萎缩。 他还提到一个细节：Every 的 Proof 是开源的，用户遇到问题，不是自己发邮件给客服，而是他们的 Agent 直接发一份 bug 报告，里面有精确的复现步骤，有对代码库的分析，直接变成 GitHub issue，然后 Every 的 Agent 去修。 这个闭环，比任何人工客服流程都快。 对 SaaS 公司来说，真正需要做的事情变了：不是把 AI 塞进自己的产品，而是让产品同时对人和 Agent 都友好，两者能在同一个界面上协作，各自看到对方在做什么。</p><h2 id="pm-和设计师-迎来最好的时代" tabindex="-1">PM 和设计师，迎来最好的时代 <a class="header-anchor" href="#pm-和设计师-迎来最好的时代" aria-label="Permalink to &quot;PM 和设计师，迎来最好的时代&quot;">​</a></h2><p>[圖 5] Dan 对这两个角色极度看好。 Marcus，PM 出身，之前在 Axios 负责写作产品，带大团队做到了几千万 ARR。 后来他休息了一年，专门学会了用 Cursor。 现在他在 Every 负责写作应用 Spiral，是团队里出货最快的人之一。 Dan 说，哪怕一年前，他们也没办法安排 Marcus 做这个工作，因为那时候模型还不够好。 但现在，Marcus 的产品感和用户洞察，配上足够好的编程模型，变成了一种超强组合。 他不需要组织一整个团队来实现自己的想法，他直接去做。 设计师也一样。 以前最大的痛苦是：想到了一个绝妙的交互，工程师不想做，或者做出来不是那个味。 现在他们可以自己发 Pull Request，自己把想法变成现实。 而且，当所有人都在用 vibe coding 批量生产千篇一律的界面时，真正懂审美、懂交互的设计师反而更值钱。 能让东西看起来不像 AI 做的，本身就是一种稀缺能力。</p><h2 id="ai-不会让你失业-但不用-ai-会" tabindex="-1">AI 不会让你失业，但不用 AI 会 <a class="header-anchor" href="#ai-不会让你失业-但不用-ai-会" aria-label="Permalink to &quot;AI 不会让你失业，但不用 AI 会&quot;">​</a></h2><p>[圖 6] Dan 的判断是：大规模失业不会发生。 那些被归因于 AI 的裁员，大多数是过度招聘的修正，AI 只是一个方便的借口。 但这不意味着可以躺平。 他给出的建议只有一条，叫&quot;骑上（驾驭）模型&quot;。 不是因为 FOMO，不是因为害怕，而是因为好奇。 每次有新模型出来，把它用在你真正在乎的事情上。 哪怕上次试过不行，这次再试一次看看。 他自己就是这么做的，GPT-5.5 出来，他把高级工程师基准重新跑了一遍，从 30 分跳到了 62 分。 他还说了一件让人意外的事：AI 的真正前沿不在旧金山，而在每一个把 AI 用在真实工作场景里的人那里。 硅谷的人在造它，但不一定知道怎么用好它。 每次新模型出来，你是世界上最早一批发现它能做什么的人之一。 Every 在布鲁克林，不在硅谷。 但 Dan 觉得他们比大多数硅谷公司都更靠近未来，原因只有一个：他们把所有工具都真的用在真实的工作上。 这是他给出的最后一个建议：别争论 AI 会不会改变世界，去找一件你真正头疼的事，试着用 AI 解决它。 当你第一次感受到&quot;这也行？&quot;的那一刻，你就不需要别人再来说服你了。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Every CEO Dan Shipper 親身驗證「AI 越強人越忙」悖論：自動化不消滅工作，而是創造管理自動化的新工作，每個 Agent 都需要一個人照料。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>「每個 Agent 需要一個人」</strong>：自動化的真正成本是管理自動化本身，這就是為什麼 Every（30 人重度 AI 公司）員工反而翻倍</li><li><strong>「高級工程師基準測試」</strong>：AI 模型普遍 30/100，GPT-5.5 達 62，人類 85-90；差距在於 AI 無法主動判斷「問題需要被重新定義」</li><li><strong>工作的兩條演化路徑</strong>：① 公司共用一個專人維護的 Agent；② AI（Codex/Claude Code）成為工作操作系統，SaaS 工具跑在 AI 裡而非 AI 嵌進 SaaS</li><li><strong>CLI 時代結束</strong>：Claude Code 的魔力不是 CLI，而是本地完整訪問權限 + 大量訓練資料</li><li><strong>SaaS 不會死</strong>：Agents 成為 SaaS 新用戶，Every 的 SaaS 支出比去年還高</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Senior Engineer Benchmark：一般模型 ~30/100、GPT-5.5 62/100、人類高級工程師 85-90/100</li><li>Every：30 人、過去一年員工翻倍、全員使用 Codex + Claude Code</li><li>Codex inbox zero：Dan 連續 10 天保持收件箱清零</li><li>新角色「前沿部署工程師」（FDE，源自 Palantir 模式）負責維護公司 Agent</li><li>工具：Codex、Claude Code、Cursor、Proof（Every 開源寫作工具）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>基準測試的自我設計偏差</strong>：Senior Engineer Benchmark 由 Dan 本人設計，未經第三方驗證，評分標準主觀（「85-90」是怎麼量的？）</li><li><strong>選擇效應</strong>：Every 是一家專門研究並輸出 AI 使用心得的媒體公司，員工增長可能反映業務擴展而非 AI 管理需求的普遍規律</li><li><strong>「AI 是 OS」願景目前仍依賴 Codex 內建瀏覽器等早期功能</strong>，可推廣性受限於工具成熟度，但方向具說服力</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>FDE 角色、公司共用 Agent、Codex 作為 OS 均為具體可落地的組織策略</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>「每個 Agent 需要一個人」、「SaaS 不會死反而受益」、「CLI 已結束」三個反共識觀點</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>第一手實戰數據真實可信，但樣本限於 Every 單一公司，基準測試自製</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>涉及 Codex/Claude Code/GPT-5.5 具體行為差異，但未深入架構細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有知識工作者和導入 AI 的組織，不限特定行業</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.7/10</strong></td><td>8×0.3+8×0.2+7×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：核心是「每個 Agent 需要一個人」、「AI 是 OS 而非工具嵌入」等可通用化的組織與思維原則</p>',32)])])}const c=a(n,[["render",i]]);export{A as __pageData,c as default};
